-- WI state-legislature stance wave 1 — roll-call derived, 125 rows
--
-- NOT a numbered migration: stance data is data, and the AZ/VA/ME/WI-Madison waves shipped the same
-- way. Generated by build_push_sql.py; that script's ADJUDICATED map is the review decision record.
--
-- Source of every row: a roll call adjudicated CHAIR-SHAPED in wi-rollcall-adjudications.json, plus
-- the member's own recorded Yes vote. Two bills qualified out of 10 adjudicated (25%):
--   AJR 102 (av0137 Assembly 54-45, sv0140 Senate 18-15) -> civil-rights chair 5
--   AB 840  (av0182 Assembly 53-44)                      -> data-centers chair 2
--
-- 72 civil-rights + 53 data-centers rows across 74 of 132 legislators.
--
-- Excluded by design: No votes (an oppositional No pins nothing), "No Vote" (that is ABSENT), and
-- Paired For/Against (a parliamentary arrangement, not an unambiguous affirmative).
--
-- politician_id resolved via office_current_holder on (chamber, district) and confirmed on FIRST AND
-- LAST name against the official roster — never on bare full_name.
-- Idempotent: every write is NOT EXISTS-guarded, so re-running is a no-op and no existing row is
-- overwritten. Verified before generating that none of these 125 (person, topic) pairs already has a
-- row: the 6 pre-existing civil-rights/data-centers rows all belong to members who voted No.

BEGIN;

-- Assembly 82 Allen, Scott — data-centers chair 2
INSERT INTO inform.politician_answers (politician_id, topic_id, value)
SELECT 'f08a79e9-42fe-4047-b7b1-ba5da9b31018'::uuid, '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid, 2
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_answers
                   WHERE politician_id = 'f08a79e9-42fe-4047-b7b1-ba5da9b31018'::uuid AND topic_id = '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid);
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT 'f08a79e9-42fe-4047-b7b1-ba5da9b31018'::uuid, '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid, 'Voted Yes on 2025 Assembly Bill 840, which directs the Public Service Commission to ensure in its rate-making orders that “no costs associated with the construction or extension of electric infrastructure that primarily serves the load of a data center are allocated to or recovered from any other customer,” and requires that any renewable energy facility primarily serving a data center be located at the data center site. The bill also mandates closed-loop cooling, annual water-use reporting to the DNR, and a reclamation bond. Those first two provisions are precisely the two clauses of this scale''s second position: requiring data centers to fund their own dedicated power generation, and barring utilities from passing data center infrastructure costs through to other customers. Recorded vote: 2025 Assembly Vote 182, 53-44.',
       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/av0182', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AB840']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = 'f08a79e9-42fe-4047-b7b1-ba5da9b31018'::uuid AND topic_id = '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid);
