                   WHERE politician_id = '450a9dfb-a01f-4ad1-b660-517e519c9c0e'::uuid AND topic_id = '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid);
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT '450a9dfb-a01f-4ad1-b660-517e519c9c0e'::uuid, '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid, 'Voted Yes on 2025 Assembly Joint Resolution 102 (second consideration), a proposed constitutional amendment creating Article I, Section 27, under which no governmental entity “may not discriminate against, or grant preferential treatment to, any individual or group on the basis of race, sex, color, ethnicity, or national origin in public employment, public education, public contracting, or public administration.” “Governmental entity” is defined to cover the state, its political subdivisions, the UW and Technical College Systems, every public school district, the legislature and the courts. The amendment''s entire purpose is to end race- and sex-conscious government programs, which is what the most restrictive position on this scale describes: eliminating affirmative action and all race-based government programs. Recorded vote: 2025 Assembly Vote 137, 54-45.',
       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/av0137', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AJR102']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = '450a9dfb-a01f-4ad1-b660-517e519c9c0e'::uuid AND topic_id = '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid);
-- Assembly 24 Knodl, Daniel — data-centers chair 2
INSERT INTO inform.politician_answers (politician_id, topic_id, value)
SELECT '5cf0f099-b460-40f4-9e1a-0663315da02d'::uuid, '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid, 2
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_answers
                   WHERE politician_id = '5cf0f099-b460-40f4-9e1a-0663315da02d'::uuid AND topic_id = '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid);
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT '5cf0f099-b460-40f4-9e1a-0663315da02d'::uuid, '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid, 'Voted Yes on 2025 Assembly Bill 840, which directs the Public Service Commission to ensure in its rate-making orders that “no costs associated with the construction or extension of electric infrastructure that primarily serves the load of a data center are allocated to or recovered from any other customer,” and requires that any renewable energy facility primarily serving a data center be located at the data center site. The bill also mandates closed-loop cooling, annual water-use reporting to the DNR, and a reclamation bond. Those first two provisions are precisely the two clauses of this scale''s second position: requiring data centers to fund their own dedicated power generation, and barring utilities from passing data center infrastructure costs through to other customers. Recorded vote: 2025 Assembly Vote 182, 53-44.',
       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/av0182', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AB840']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = '5cf0f099-b460-40f4-9e1a-0663315da02d'::uuid AND topic_id = '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid);
