       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/av0182', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AB840']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = '6293d49b-6a86-41c1-9e2e-5f9ec8188924'::uuid AND topic_id = '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid);
-- Assembly 38 Penterman, William — civil-rights chair 5
INSERT INTO inform.politician_answers (politician_id, topic_id, value)
SELECT '6293d49b-6a86-41c1-9e2e-5f9ec8188924'::uuid, '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid, 5
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_answers
                   WHERE politician_id = '6293d49b-6a86-41c1-9e2e-5f9ec8188924'::uuid AND topic_id = '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid);
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT '6293d49b-6a86-41c1-9e2e-5f9ec8188924'::uuid, '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid, 'Voted Yes on 2025 Assembly Joint Resolution 102 (second consideration), a proposed constitutional amendment creating Article I, Section 27, under which no governmental entity “may not discriminate against, or grant preferential treatment to, any individual or group on the basis of race, sex, color, ethnicity, or national origin in public employment, public education, public contracting, or public administration.” “Governmental entity” is defined to cover the state, its political subdivisions, the UW and Technical College Systems, every public school district, the legislature and the courts. The amendment''s entire purpose is to end race- and sex-conscious government programs, which is what the most restrictive position on this scale describes: eliminating affirmative action and all race-based government programs. Recorded vote: 2025 Assembly Vote 137, 54-45.',
       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/av0137', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AJR102']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = '6293d49b-6a86-41c1-9e2e-5f9ec8188924'::uuid AND topic_id = '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid);
