SELECT '94794832-a1f2-475f-93eb-2e8d896fd8be'::uuid, '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid, 'Voted Yes on 2025 Assembly Bill 840, which directs the Public Service Commission to ensure in its rate-making orders that “no costs associated with the construction or extension of electric infrastructure that primarily serves the load of a data center are allocated to or recovered from any other customer,” and requires that any renewable energy facility primarily serving a data center be located at the data center site. The bill also mandates closed-loop cooling, annual water-use reporting to the DNR, and a reclamation bond. Those first two provisions are precisely the two clauses of this scale''s second position: requiring data centers to fund their own dedicated power generation, and barring utilities from passing data center infrastructure costs through to other customers. Recorded vote: 2025 Assembly Vote 182, 53-44.',
       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/av0182', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AB840']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = '94794832-a1f2-475f-93eb-2e8d896fd8be'::uuid AND topic_id = '4559b513-0fd8-4ed1-babd-f3b554162f40'::uuid);
