       ARRAY['https://docs.legis.wisconsin.gov/document/votes/2025/sv0140', 'https://docs.legis.wisconsin.gov/document/proposaltext/2025/REG/AJR102']::text[]
WHERE NOT EXISTS (SELECT 1 FROM inform.politician_context
                   WHERE politician_id = '908761b2-ab7f-4307-a073-a5a00e220b43'::uuid AND topic_id = '0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid);
